import { test } from 'node:test';
import assert from 'node:assert/strict';
import { executarEmSerie, executarComLimite } from './solution.mjs';

test('executarEmSerie devolve os resultados na ordem das tarefas', async () => {
  const tarefas = [
    () => new Promise((resolve) => setTimeout(resolve, 3, 'a')),
    () => new Promise((resolve) => setTimeout(resolve, 2, 'b')),
  ];
  assert.deepEqual(await executarEmSerie(tarefas), ['a', 'b']);
});

test('executarEmSerie começa a segunda tarefa só depois da primeira terminar', async () => {
  const inicio = [];
  const tarefas = [
    () => {
      inicio.push(['a', Date.now()]);
      return new Promise((resolve) => setTimeout(resolve, 5, 'a'));
    },
    () => {
      inicio.push(['b', Date.now()]);
      return new Promise((resolve) => setTimeout(resolve, 2, 'b'));
    },
  ];
  await executarEmSerie(tarefas);
  assert.equal(inicio.length, 2);
  assert.ok(
    inicio[1][1] - inicio[0][1] >= 4,
    'a segunda tarefa deve esperar a primeira terminar',
  );
});

test('executarEmSerie com lista vazia devolve lista vazia', async () => {
  assert.deepEqual(await executarEmSerie([]), []);
});

test('executarComLimite respeita o limite e devolve os resultados na ordem', async () => {
  let ativas = 0;
  let pico = 0;
  const tarefas = [1, 2, 3, 4].map((i) => () => {
    ativas += 1;
    pico = Math.max(pico, ativas);
    return new Promise((resolve) => {
      setTimeout(() => {
        ativas -= 1;
        resolve('t' + i);
      }, 4);
    });
  });
  const resultados = await executarComLimite(tarefas, 2);
  assert.deepEqual(resultados, ['t1', 't2', 't3', 't4']);
  assert.ok(pico <= 2, 'nunca deve haver mais de 2 tarefas ao mesmo tempo');
  assert.ok(pico >= 2, 'as fatias devem rodar tarefas ao mesmo tempo');
});

