export async function executarEmSerie(tarefas) {
  const resultados = [];
  for (const tarefa of tarefas) {
    // o await no laço: a próxima só começa quando a atual termina
    resultados.push(await tarefa());
  }
  return resultados;
}

export async function executarComLimite(tarefas, limite) {
  const resultados = [];
  for (let i = 0; i < tarefas.length; i += limite) {
    // fatia de até `limite` tarefas: dispara juntas e espera a fatia
    const fatia = tarefas.slice(i, i + limite);
    resultados.push(...(await Promise.all(fatia.map((tarefa) => tarefa()))));
  }
  return resultados;
}
